// Junta todo lo de los últimos 7 días en un solo mensaje.
const zona = 'America/Havana';
const ahora = $now.setZone(zona);
const desde = ahora.minus({ days: 7 });
const hoy = ahora.startOf('day');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Las columnas de fecha guardan el día a medianoche UTC: se leen en UTC para no correr un día.
const dia = d => DateTime.fromISO(String(d), { zone: 'utc' }).toISODate();
const fecha = d => d ? DateTime.fromISO(String(d), { zone: 'utc' }).toFormat('dd/MM') : '—';
// Recorta en un espacio, nunca a mitad de palabra.
const corto = (s, n) => { s = String(s || ''); if (s.length <= n) return s; const c = s.slice(0, n); return c.slice(0, Math.max(c.lastIndexOf(' '), n * 0.6)).replace(/[\s,.;:]+$/, '') + '…'; };
const recientes = (d) => d && DateTime.fromISO(String(d)) >= desde;
const L = [];
L.push(`<b>Resumen semanal</b> · ${desde.toFormat('dd/MM')} – ${ahora.toFormat('dd/MM')}`);

// Clientes
const leads = ($('Leads').first().json.data || []).filter(r => recientes(r.fecha));
const buenos = leads.filter(r => r.calidad === 'bueno');
const sinResponder = ($('Leads').first().json.data || []).filter(r => r.estado === 'nuevo');
L.push('', `<b>📬 Clientes</b>`);
if (!leads.length) L.push('Ningún lead nuevo esta semana.');
else {
  L.push(`${leads.length} leads · ${buenos.length} buenos`);
  for (const r of [...leads].sort((a, b) => (b.puntuacion || 0) - (a.puntuacion || 0)).slice(0, 5))
    L.push(`• ${esc(r.nombre || r.correo)} · ${esc(r.tipo || '?')} · ${r.puntuacion ?? '?'}/10`);
}
if (sinResponder.length) L.push(`⚠️ ${sinResponder.length} sin responder a mano: ${sinResponder.slice(0, 4).map(r => esc(r.nombre || r.correo)).join(', ')}`);

// Prospección
const prosp = $('Prospección').first().json.data || [];
const porEstado = {};
for (const r of prosp) porEstado[r.estado || 'sin estado'] = (porEstado[r.estado || 'sin estado'] || 0) + 1;
L.push('', `<b>🎯 Prospección</b>`);
L.push(prosp.length ? Object.entries(porEstado).map(([k, v]) => `${k}: ${v}`).join(' · ') : 'Sin servidores en la tabla.');
const limite = hoy.plus({ days: 7 }).toISODate();
const seguir = prosp.filter(r => r.proximo_seguimiento && !['ganado', 'perdido'].includes(r.estado) && dia(r.proximo_seguimiento) <= limite)
  .sort((a, b) => String(a.proximo_seguimiento).localeCompare(String(b.proximo_seguimiento)));
for (const r of seguir) {
  const vencido = dia(r.proximo_seguimiento) < hoy.toISODate();
  L.push(`${vencido ? '🔴' : '•'} ${fecha(r.proximo_seguimiento)} · <b>${esc(r.servidor)}</b> (${esc(r.estado)}) — ${esc(corto(r.nota, 160))}`);
}

// n8n
const nombres = Object.fromEntries(($('Flujos').first().json.data || []).map(w => [w.id, w.name]));
const ejec = $('Ejecuciones').all().flatMap(i => i.json.data || []).filter(e => recientes(e.startedAt));
const porFlujo = {};
for (const e of ejec) {
  const f = porFlujo[e.workflowId] ||= { ok: 0, error: 0, reintentos: 0 };
  if (e.status === 'success') f.ok++; else if (['error', 'crashed'].includes(e.status)) f.error++;
  if (e.retryOf) f.reintentos++;
}
const errores = Object.values(porFlujo).reduce((s, f) => s + f.error, 0);
L.push('', `<b>⚙️ n8n</b>`);
L.push(`${ejec.length} ejecuciones guardadas · ${errores} con error`);
for (const [id, f] of Object.entries(porFlujo).sort((a, b) => b[1].error - a[1].error).slice(0, 6))
  L.push(`• ${esc(nombres[id] || id)}: ${f.ok} ok${f.error ? ` · <b>${f.error} error</b>` : ''}${f.reintentos ? ` · ${f.reintentos} reintentos` : ''}`);

// GitHub
const eventos = ($('Eventos GitHub').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json])).filter(e => e && recientes(e.created_at));
const pushes = eventos.filter(e => e.type === 'PushEvent');
const commits = pushes.reduce((s, e) => s + (e.payload?.size ?? e.payload?.commits?.length ?? 1), 0);
const repos = [...new Set(pushes.map(e => e.repo.name.split('/')[1]))];
const nuevos = eventos.filter(e => e.type === 'CreateEvent' && e.payload?.ref_type === 'repository').map(e => e.repo.name.split('/')[1]);
const misRepos = $('Repos GitHub').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(r => r && !r.fork);
const estrellas = misRepos.reduce((s, r) => s + (r.stargazers_count || 0), 0);
L.push('', `<b>🐙 GitHub</b>`);
L.push(`${commits} commits en ${repos.length} repos públicos · ⭐ ${estrellas} en total`);
if (repos.length) L.push(`Repos: ${repos.slice(0, 6).map(esc).join(', ')}`);
if (nuevos.length) L.push(`Nuevos: ${nuevos.map(esc).join(', ')}`);

return [{ json: { texto: L.join('\n') } }];
